mapper.select:
SELECT *
FROM t_ai_chat_history
WHERE conversation_id = #{conversationId}
  AND deleted_flag = false
ORDER BY create_time ASC

    LIMIT #{limit}

mapper.update:
UPDATE t_ai_chat_history
SET deleted_flag = true
WHERE conversation_id = #{conversationId}

mapper.select:
SELECT *
FROM t_ai_chat_history
WHERE user_id = #{userId}
  AND deleted_flag = false
ORDER BY create_time DESC

    LIMIT #{limit}
